CREATE TABLE app_user (id BIGINT IDENTITY PRIMARY KEY, email NVARCHAR(255) NOT NULL UNIQUE, password_hash NVARCHAR(255) NOT NULL, role NVARCHAR(20) NOT NULL, full_name NVARCHAR(160) NOT NULL, active BIT NOT NULL DEFAULT 1, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE patient (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES app_user(id), nic NVARCHAR(30) NOT NULL UNIQUE, date_of_birth DATE NOT NULL, phone NVARCHAR(30) NOT NULL, address NVARCHAR(300), contact_preference NVARCHAR(20) NOT NULL DEFAULT 'IN_APP');
CREATE TABLE emergency_contact (id BIGINT IDENTITY PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patient(id), full_name NVARCHAR(160) NOT NULL, relationship NVARCHAR(80) NOT NULL, phone NVARCHAR(30) NOT NULL);
CREATE TABLE specialty (id BIGINT IDENTITY PRIMARY KEY, name NVARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE doctor (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NULL UNIQUE REFERENCES app_user(id), specialty_id BIGINT NOT NULL REFERENCES specialty(id), department NVARCHAR(100) NOT NULL, room NVARCHAR(30), fee DECIMAL(12,2) NOT NULL, active BIT NOT NULL DEFAULT 1);
CREATE TABLE schedule_template (id BIGINT IDENTITY PRIMARY KEY, doctor_id BIGINT NOT NULL REFERENCES doctor(id), day_of_week INT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, slot_minutes INT NOT NULL, capacity INT NOT NULL, active BIT NOT NULL DEFAULT 1);
CREATE TABLE slot (id BIGINT IDENTITY PRIMARY KEY, doctor_id BIGINT NOT NULL REFERENCES doctor(id), starts_at DATETIME2 NOT NULL, ends_at DATETIME2 NOT NULL, status NVARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', version INT NOT NULL DEFAULT 0, CONSTRAINT uq_doctor_slot UNIQUE(doctor_id, starts_at), CONSTRAINT ck_slot_status CHECK(status IN ('AVAILABLE','BOOKED','BLOCKED')));
CREATE TABLE appointment (id BIGINT IDENTITY PRIMARY KEY, patient_id BIGINT NOT NULL REFERENCES patient(id), slot_id BIGINT NOT NULL REFERENCES slot(id), status NVARCHAR(20) NOT NULL, booked_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT ck_appointment_status CHECK(status IN ('CONFIRMED','CHECKED_IN','CALLED','COMPLETED','CANCELLED')));
CREATE INDEX ix_appointment_patient ON appointment(patient_id, booked_at);
CREATE TABLE queue_token (id BIGINT IDENTITY PRIMARY KEY, appointment_id BIGINT NOT NULL UNIQUE REFERENCES appointment(id), doctor_id BIGINT NOT NULL REFERENCES doctor(id), queue_date DATE NOT NULL, token_number INT NOT NULL, status NVARCHAR(20) NOT NULL DEFAULT 'WAITING', checked_in_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), called_at DATETIME2 NULL, completed_at DATETIME2 NULL, CONSTRAINT uq_queue_number UNIQUE(doctor_id, queue_date, token_number));
CREATE TABLE demo_payment (id BIGINT IDENTITY PRIMARY KEY, appointment_id BIGINT NOT NULL UNIQUE REFERENCES appointment(id), amount DECIMAL(12,2) NOT NULL, choice NVARCHAR(30) NOT NULL, status NVARCHAR(30) NOT NULL, recorded_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE notification (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id), appointment_id BIGINT NULL REFERENCES appointment(id), type NVARCHAR(40) NOT NULL, message NVARCHAR(500) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), read_at DATETIME2 NULL, due_at DATETIME2 NULL, CONSTRAINT uq_notification_due UNIQUE(appointment_id,type,due_at));
CREATE TABLE audit_event (id BIGINT IDENTITY PRIMARY KEY, actor_user_id BIGINT NULL REFERENCES app_user(id), action NVARCHAR(80) NOT NULL, entity_name NVARCHAR(80) NOT NULL, entity_id BIGINT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
